    antiphon: { pos: "n.", zh: "交互輪唱的歌；輪唱讚美詩", level: 3, diff: 95, ex: "The choir sang an antiphon, alternating verses with the congregation.", exZh: "合唱團唱了一首輪唱讚美詩，與會眾交替吟唱各節。" },
    antiphony: { pos: "n.", zh: "交互輪唱；輪唱讚美詩", level: 3, diff: 90, ex: "The choir used antiphony, with one group singing a line and the other answering.", exZh: "合唱團採用交互輪唱，一組唱一句，另一組接著應答。" },
    antipodes: { pos: "n.", zh: "澳大利亞和紐西蘭", level: 3, diff: 85, ex: "For many Europeans, Australia and New Zealand were the antipodes.", exZh: "對許多歐洲人來說，澳大利亞和紐西蘭就是地球另一端的地方。" },
    antiquary: { pos: "n.", zh: "研究（或收藏", level: 3, diff: 85, ex: "The antiquary spent years studying Roman coins and pottery.", exZh: "這位古文物家多年來研究羅馬錢幣和陶器。" },
    antiquate: { pos: "v.", zh: "使古舊；使過時；廢棄", level: 3, diff: 90, ex: "Rapid advances in technology can antiquate a device within a few years.", exZh: "科技的快速進步可能在幾年內就使一台設備過時。" },
    antique: { pos: "adj./n.", zh: "古董的", level: 2, diff: 50, ex: "They bought an antique table at the market.", exZh: "他們在市場買了一張古董桌。" },
    antiseptic: { pos: "n.", zh: "防腐劑；（尤指）殺菌劑，消毒劑", level: 2, diff: 55, ex: "The nurse cleaned the cut with an antiseptic before bandaging it.", exZh: "護士在包紮傷口前，先用消毒劑清洗傷口。" },
    antislavery: { pos: "adj.", zh: "反奴隸制的", level: 2, diff: 65, ex: "She joined an antislavery organization.", exZh: "她加入了一個反奴隸制組織。" },
    antispasmodic: { pos: "adj.", zh: "止痙攣的", level: 3, diff: 90, ex: "The doctor prescribed an antispasmodic medicine to relieve her muscle cramps.", exZh: "醫師開了一種止痙攣的藥，以緩解她的肌肉痙攣。" },
    antistrophe: { pos: "n.", zh: "向右轉時的回舞歌；交錯詩節中的第二詩節及其類似詩節", level: 3, diff: 95, ex: "In the ancient Greek performance, the chorus sang an antistrophe while turning to the right.", exZh: "在這場古希臘演出中，合唱隊一邊向右轉，一邊唱回舞歌。" },
    antitoxin: { pos: "n.", zh: "抗毒素", level: 3, diff: 80, ex: "The patient received antitoxin to neutralize the toxin.", exZh: "病人接受了抗毒素來中和毒素。" },
    antonym: { pos: "n.", zh: "反義詞", level: 2, diff: 45, ex: "“Hot” is an antonym of “cold.”", exZh: "「Hot」（熱）是「cold」（冷）的反義詞。" },
    anxious: { pos: "adj.", zh: "焦慮的", level: 1, diff: 40, ex: "He was anxious to hear the results.", exZh: "他渴望得知結果。" },
    aperture: { pos: "n.", zh: "小孔；縫隙；（尤指照相機的）孔徑，光圈", level: 2, diff: 65, ex: "A wider aperture lets more light into the camera.", exZh: "較大的光圈會讓更多光線進入相機。" },
    apex: { pos: "n.", zh: "頂點；巔峰", level: 2, diff: 60, ex: "She reached the apex of her career at forty.", exZh: "她在四十歲時達到事業的巔峰。" },
    aphorism: { pos: "n.", zh: "格言，警句", level: 3, diff: 80, ex: "She ended her speech with an aphorism: “Actions speak louder than words.”", exZh: "她以一句格言結束演講：「行動勝於言語。」" },
