    apogee: { pos: "n.", zh: "頂峰，頂點，最高點", level: 3, diff: 85, ex: "Her popularity reached its apogee after the hit film was released.", exZh: "那部熱門電影上映後，她的人氣達到了頂峰。" },
    apology: { pos: "n.", zh: "道歉", level: 1, diff: 35, ex: "Her apology for the mistake sounded sincere.", exZh: "她為那個錯誤所作的道歉聽起來很誠懇。" },
    apostasy: { pos: "n.", zh: "叛教；變節；脫黨", level: 3, diff: 85, ex: "His apostasy shocked the congregation.", exZh: "他的叛教令會眾震驚。" },
    apostate: { pos: "adj./n.", zh: "放棄信仰的；脫黨的；變節的", level: 3, diff: 85, ex: "The apostate left the faith and joined another religion.", exZh: "這名叛教者離開了原本的信仰，改信另一種宗教。" },
    apostle: { pos: "n.", zh: "宣導者，鼓吹者，先驅", level: 3, diff: 75, ex: "She became an apostle of education reform, urging others to support the movement.", exZh: "她成了教育改革的倡導者，敦促其他人支持這場運動。" },
    apothecary: { pos: "n.", zh: "藥劑師，藥商", level: 3, diff: 85, ex: "The village apothecary prepared remedies and sold them from his shop.", exZh: "村裡的藥劑師兼藥商調製藥品，並在店裡販售。" },
    apotheosis: { pos: "n.", zh: "典範；最完美的榜樣；極致", level: 3, diff: 90, ex: "For many fans, her final performance was the apotheosis of theatrical brilliance.", exZh: "對許多影迷而言，她最後的演出是戲劇才華的極致。" },
    appall: { pos: "v.", zh: "使驚駭；使震驚", level: 3, diff: 75, ex: "We were appalled at the news of the accident.", exZh: "聽到這起意外的消息,我們都嚇壞了。" },
    apparent: { pos: "adj.", zh: "明顯的", level: 2, diff: 50, ex: "The apparent simplicity of the task hid its real difficulty.", exZh: "這項任務表面上的簡單掩蓋了它真正的難度。" },
    apparition: { pos: "n.", zh: "鬼，鬼魂，幽靈", level: 3, diff: 75, ex: "A pale apparition appeared at the end of the hallway.", exZh: "一個蒼白的幽靈出現在走廊盡頭。" },
    appease: { pos: "v.", zh: "平息；撫慰；綏靖", level: 3, diff: 70, ex: "The manager offered a refund to appease the angry customer.", exZh: "經理提出退款，以安撫那位生氣的顧客。" },
