    append: { pos: "v.", zh: "附加，增補", level: 1, diff: 40, ex: "Please append a short note to the end of the article.", exZh: "請在文章末尾附加一則簡短註記。" },
    appertain: { pos: "v.", zh: "屬於；有關", level: 3, diff: 85, ex: "These rules appertain to all new members.", exZh: "這些規定適用於所有新成員。" },
    apposite: { pos: "adj.", zh: "適當的；恰當的；貼切的", level: 3, diff: 85, ex: "Her apposite comment brought the discussion back to the main issue.", exZh: "她恰當的評論讓討論回到主要議題上。" },
    apposition: { pos: "n.", zh: "同位（關係）；同位語", level: 3, diff: 75, ex: "In “my friend Maya,” the name Maya is in apposition to “my friend.”", exZh: "在「我的朋友瑪雅」這個片語中，名字「瑪雅」與「我的朋友」構成同位關係。" },
