    appreciable: { pos: "adj.", zh: "明顯的；可察覺的；值得重視的", level: 2, diff: 65, ex: "The new insulation made an appreciable difference to the room's temperature.", exZh: "新的隔熱材料讓房間的溫度有了明顯的變化。" },
