    aqueduct: { pos: "n.", zh: "高架渠，渡槽", level: 3, diff: 80, ex: "The aqueduct crossed the valley on a series of arches.", exZh: "這條渡槽以一連串拱門跨越山谷。" },
    aqueous: { pos: "adj.", zh: "水的；似水的；含水的", level: 3, diff: 70, ex: "The medicine is an aqueous solution containing mostly water.", exZh: "這種藥物是主要由水構成的水溶液。" },
    arbitrate: { pos: "v.", zh: "仲裁，裁決，公斷", level: 3, diff: 75, ex: "Both companies asked a neutral expert to arbitrate their dispute.", exZh: "兩家公司都請一位中立專家仲裁他們的爭議。" },
