    artful: { pos: "adj.", zh: "巧妙的，機靈的，取巧的", level: 3, diff: 70, ex: "He used an artful excuse to get the day off.", exZh: "他巧妙地編了個藉口，好讓自己請到一天假。" },
    arthurian: { pos: "adj.", zh: "亞瑟王的(傳奇)的", level: 3, diff: 75, ex: "The novel retells an Arthurian legend.", exZh: "這部小說重新講述了一則亞瑟王傳奇。" },
