    artless: { pos: "adj.", zh: "單純的，直率的；不詭詐的", level: 2, diff: 65, ex: "Her artless honesty made it clear she was not trying to deceive anyone.", exZh: "她單純直率的誠實態度，讓人看得出她並沒有試圖欺騙任何人。" },
