    ascension: { pos: "n.", zh: "升職；提升", level: 3, diff: 70, ex: "Her ascension to the director role surprised her colleagues.", exZh: "她升任董事一職，令同事們感到意外。" },
    ascribe: { pos: "v.", zh: "把…歸因於", level: 2, diff: 65, ex: "She ascribed her success to hard work.", exZh: "她把成功歸因於努力工作。" },
    asexual: { pos: "adj.", zh: "無性的；無性器官的", level: 2, diff: 65, ex: "This organism is asexual and reproduces without a mate.", exZh: "這種生物是無性的，不需要配偶便能繁殖。" },
    ashen: { pos: "adj.", zh: "灰色的；蒼白的", level: 2, diff: 65, ex: "His face turned ashen when he heard the news.", exZh: "他聽到這個消息後，臉色變得蒼白。" },
    askance: { pos: "adv.", zh: "懷疑地；不讚許地；斜著眼睛", level: 3, diff: 80, ex: "She looked askance at his proposal.", exZh: "她不以為然地看著他的提議。" },
    aspirant: { pos: "n.", zh: "抱負不凡者；有志者", level: 2, diff: 65, ex: "The young aspirant worked hard to become a surgeon.", exZh: "這位年輕的有志者努力學習，希望成為一名外科醫生。" },
