    assailant: { pos: "n.", zh: "攻擊者", level: 2, diff: 65, ex: "The assailant fled before the police arrived.", exZh: "襲擊者在警方抵達前逃走了。" },
    assassin: { pos: "n.", zh: "暗殺者，行刺者，刺客", level: 3, diff: 70, ex: "The assassin was hired to kill the president.", exZh: "這名刺客受雇刺殺總統。" },
    assassinate: { pos: "v.", zh: "暗殺，行刺", level: 3, diff: 70, ex: "The plot was to assassinate the president.", exZh: "這項陰謀是要暗殺總統。" },
    assassination: { pos: "n.", zh: "暗殺（名人或重要人物）", level: 2, diff: 60, ex: "The assassination of the president shocked the nation.", exZh: "總統遭暗殺震驚了全國。" },
