    assess: { pos: "v.", zh: "評估", level: 2, diff: 50, ex: "The appraiser will assess the house before setting its price.", exZh: "估價師會先評估這棟房子，再訂定價格。" },
    assessor: { pos: "n.", zh: "估價員；審核員", level: 2, diff: 55, ex: "The assessor valued the house at $400,000.", exZh: "估價員將這棟房子的價值評定為四十萬美元。" },
    assets: { pos: "n.", zh: "優點，長處；有用的人", level: 2, diff: 45, ex: "Her patience and clear communication skills are valuable assets to the team.", exZh: "她的耐心和清晰的溝通能力是團隊的寶貴優點。" },
