    ministration: { pos: "n.", zh: "行宗教儀式；服侍；援助", level: 3, diff: 85, ex: "The priest's ministration during the baptism comforted the family.", exZh: "牧師在洗禮儀式中的服侍安慰了這個家庭。" },
