    misadventure: { pos: "n.", zh: "不幸事故；不幸遭遇；厄運", level: 3, diff: 75, ex: "Their camping trip turned into a misadventure when a storm flooded the tent.", exZh: "一場暴風雨淹沒了帳篷，他們的露營之旅因此變成一場不幸遭遇。" },
    misanthropic: { pos: "adj.", zh: "厭惡人類的；遁世的，不與他人交往的", level: 3, diff: 85, ex: "The misanthropic writer avoided parties and preferred to be alone.", exZh: "那位厭惡人類的作家避開派對，寧願獨處。" },
