    misogyny: { pos: "n.", zh: "厭女症，女性貶抑", level: 3, diff: 80, ex: "Misogyny can appear in jokes that demean women.", exZh: "厭女思想可能出現在貶低女性的笑話中。" },
    misplace: { pos: "v.", zh: "隨意擱置；亂放（而一時找不到）", level: 2, diff: 45, ex: "I sometimes misplace my glasses and spend ten minutes looking for them.", exZh: "我有時會把眼鏡亂放，然後花十分鐘找它們。" },
