    transcontinental: { pos: "adj.", zh: "橫貫大陸的；大陸那邊的", level: 2, diff: 60, ex: "The transcontinental railway connects the country’s east and west coasts.", exZh: "這條橫貫大陸的鐵路連接該國東西兩岸。" },
    transcribe: { pos: "v.", zh: "抄寫，謄寫；把（資料）改錄成另一種形式", level: 2, diff: 65, ex: "Please transcribe the interview into a written document.", exZh: "請把這段訪談謄寫成文字文件。" },
    transcript: { pos: "n.", zh: "成績單；錄音文字謄本抄本", level: 2, diff: 60, ex: "I checked the transcript against the recording for errors.", exZh: "我對照錄音檢查謄本是否有錯誤。" },
    transfer: { pos: "v./n.", zh: "轉學；轉移", level: 2, diff: 50, ex: "She transferred to a new school.", exZh: "她轉到了一所新學校。" },
    transferable: { pos: "adj.", zh: "可轉移的；可轉印的", level: 2, diff: 55, ex: "The image is transferable to fabric using iron-on transfer paper.", exZh: "這張圖像可以用燙印轉印紙轉印到布料上。" },
