    transference: { pos: "n.", zh: "轉移；傳遞；調任", level: 3, diff: 75, ex: "The transference of funds to her new account took two days.", exZh: "款項轉入她的新帳戶花了兩天。" },
    transferrer: { pos: "n.", zh: "讓渡人；讓賣人（= transferor）", level: 3, diff: 90, ex: "The transferrer signed the deed before the property was transferred.", exZh: "讓渡人在財產移轉前簽署了契據。" },
    transfigure: { pos: "v.", zh: "使改觀；使變形", level: 3, diff: 85, ex: "Love transfigured the old man's face.", exZh: "愛讓老人的臉煥然一新。" },
    transfuse: { pos: "v.", zh: "輸（血）；注入", level: 3, diff: 75, ex: "Doctors transfused blood into the injured man.", exZh: "醫生為受傷的男子輸血。" },
    transfusible: { pos: "adj.", zh: "可傾注的；可灌輸的；可輸血的", level: 3, diff: 80, ex: "The donor's blood was tested to make sure it was transfusible to the patient.", exZh: "捐贈者的血液經過檢驗，以確保可以輸給病人。" },
    transfusion: { pos: "n.", zh: "傾注，灌輸；滲透；輸血", level: 3, diff: 75, ex: "She needed a blood transfusion after the accident.", exZh: "她在事故後需要輸血。" },
    transgress: { pos: "v.", zh: "違反，違背（規則", level: 3, diff: 75, ex: "The company must not transgress the limits set by law.", exZh: "公司不得逾越法律所訂定的界限。" },
    transience: { pos: "n.", zh: "頃刻；無常；短暫", level: 3, diff: 75, ex: "The poem reflects on the transience of life.", exZh: "這首詩反思生命的無常。" },
    transition: { pos: "n./v.", zh: "過渡；過渡時期；轉變，變遷", level: 2, diff: 60, ex: "The transition from school to work can be challenging.", exZh: "從學校到職場的過渡可能很具挑戰性。" },
    transitory: { pos: "adj.", zh: "短暫的；瞬息的；無常的", level: 3, diff: 75, ex: "Their happiness was transitory, fading after only a few days.", exZh: "他們的快樂是短暫的，幾天後便消逝了。" },
