    transparent: { pos: "adj.", zh: "透明的；清澈的；顯而易見的", level: 2, diff: 50, ex: "His excuse was so transparent that nobody believed it.", exZh: "他的藉口顯而易見，沒有人相信。" },
    transpire: { pos: "v.", zh: "被人知道；發生", level: 3, diff: 75, ex: "It later transpired that he had lied.", exZh: "後來才發現原來他說了謊。" },
    transplant: { pos: "v.", zh: "移植；移種；(使)移居", level: 2, diff: 60, ex: "They transplant young trees from the nursery to the hillside each spring.", exZh: "他們每年春天都把幼樹從苗圃移植到山坡上。" },
