    transverse: { pos: "adj.", zh: "橫向的；橫斷的；橫切的", level: 3, diff: 75, ex: "A transverse beam supports the roof across its width.", exZh: "一根橫向梁沿著屋頂的寬度支撐屋頂。" },
    travail: { pos: "n.", zh: "艱苦勞動，辛勤工作；痛苦，艱難", level: 3, diff: 85, ex: "After months of travail, the team finally completed the bridge.", exZh: "經過數月的艱辛努力，團隊終於完成了這座橋。" },
    travesty: { pos: "n./v.", zh: "滑稽模仿；拙劣的模仿；歪曲", level: 3, diff: 75, ex: "The film was a travesty of the novel, reducing its complex characters to jokes.", exZh: "這部電影是對那部小說的拙劣歪曲，把複雜的人物都簡化成笑話。" },
    treacherous: { pos: "adj.", zh: "背叛的；不忠的；奸詐的", level: 3, diff: 75, ex: "The treacherous path became slippery after the rain.", exZh: "那條危險難行的小路在雨後變得濕滑。" },
    treachery: { pos: "n.", zh: "背叛，變節；背信；背叛（或變節）行為", level: 3, diff: 75, ex: "The general was accused of treachery after secretly helping the enemy.", exZh: "那名將軍因暗中幫助敵人而被指控背叛。" },
    treasonable: { pos: "adj.", zh: "叛逆的；不忠的；背信的", level: 3, diff: 85, ex: "The officials accused him of making treasonable plans to overthrow the government.", exZh: "官員指控他制定了叛逆計畫，企圖推翻政府。" },
    treatise: { pos: "n.", zh: "論文；專著", level: 3, diff: 80, ex: "She wrote a treatise on medieval law.", exZh: "她寫了一部關於中世紀法律的專著。" },
    treble: { pos: "adj./n./v.", zh: "三倍的，三重的；最高聲部的", level: 2, diff: 65, ex: "She sang the treble part in the choir.", exZh: "她在合唱團中唱最高聲部。" },
    trebly: { pos: "adv.", zh: "三倍地；三重地；高聲地", level: 3, diff: 90, ex: "The child’s laugh rang trebly through the room.", exZh: "孩子的笑聲以尖亮的高音響徹房間。" },
    tremendous: { pos: "adj.", zh: "巨大", level: 2, diff: 55, ex: "The storm caused tremendous damage to the village.", exZh: "這場暴風雨對村莊造成了巨大的損害。" },
    tremor: { pos: "n.", zh: "震顫；顫抖；震動", level: 2, diff: 55, ex: "A slight tremor shook the windows during the storm.", exZh: "暴風雨期間，一陣輕微的震動搖晃了窗戶。" },
