    triple: { pos: "adj./n./v.", zh: "三倍的；三重的；由三部分構成的", level: 1, diff: 40, ex: "We need to triple the recipe to feed everyone.", exZh: "我們得把食譜的份量增加到三倍，才能餵飽大家。" },
