    triplicity: { pos: "n.", zh: "三個一組；三位一體；三倍（性）", level: 3, diff: 95, ex: "In astrology, a triplicity consists of three zodiac signs separated by 120 degrees.", exZh: "在占星術中，一組三宮由彼此相隔120度的三個黃道星座組成。" },
