    turgid: { pos: "adj.", zh: "腫脹的，浮腫的；（言詞等）浮誇的；誇張的", level: 3, diff: 80, ex: "The report was written in turgid, exaggerated language.", exZh: "這份報告使用了浮誇、誇張的語言。" },
    turpitude: { pos: "n.", zh: "奸惡；卑鄙；墮落", level: 3, diff: 90, ex: "The court found that his fraud involved moral turpitude.", exZh: "法院認定他的詐欺行為涉及道德上的卑劣。" },
    tutelage: { pos: "n.", zh: "保護；監護；指導", level: 3, diff: 75, ex: "Under her tutelage, the young pianist mastered the concerto.", exZh: "在她的指導下，這位年輕鋼琴家熟練掌握了這首協奏曲。" },
    tutelar: { pos: "adj.", zh: "保護的；監護的；保護人的", level: 3, diff: 95, ex: "The tutelar deity was believed to protect the village.", exZh: "人們相信那位守護神會保護村莊。" },
