    tyrannical: { pos: "adj.", zh: "暴君的；專制君主的；暴君似的", level: 3, diff: 75, ex: "The tyrannical ruler imprisoned anyone who opposed him.", exZh: "這位暴虐的統治者把所有反對他的人都關進了監獄。" },
    tyranny: { pos: "n.", zh: "暴政；專制；暴虐，專橫", level: 2, diff: 65, ex: "The people rose up against the tyranny of the king.", exZh: "人民起來反抗國王的暴政。" },
    ulterior: { pos: "adj.", zh: "隱祕不明的，別有用心的；在那邊的；較遠的", level: 3, diff: 75, ex: "She suspected he had an ulterior motive for offering help.", exZh: "她懷疑他主動幫忙是別有用心。" },
