    ultramundane: { pos: "adj.", zh: "太陽系以外的；世界以外的；超俗的", level: 3, diff: 90, ex: "The signal seemed to come from an ultramundane intelligence beyond Earth.", exZh: "這訊號似乎來自地球以外的超俗智慧生命。" },
    umbrage: { pos: "n.", zh: "陰影；樹蔭；（成蔭的）簇葉", level: 3, diff: 90, ex: "We rested beneath the umbrage of the old oak.", exZh: "我們在老橡樹的樹蔭下休息。" },
    unaccountable: { pos: "adj.", zh: "無法解釋的，不可理解的；莫名其妙的；無責任的", level: 3, diff: 70, ex: "There was an unaccountable delay in the delivery.", exZh: "送貨出現了莫名其妙的延誤。" },
    unaffected: { pos: "adj.", zh: "不受影響的；純真的；不裝腔作勢的", level: 2, diff: 60, ex: "Her unaffected manner made everyone feel at ease.", exZh: "她不矯揉造作的舉止讓每個人都感到自在。" },
