    unanimous: { pos: "adj.", zh: "全體一致贊同的；無異議的", level: 2, diff: 50, ex: "The committee was unanimous in its support for the proposal.", exZh: "委員會全體一致支持這項提案。" },
    unavoidable: { pos: "adj.", zh: "不可避免的", level: 2, diff: 50, ex: "A delay was unavoidable because of the storm.", exZh: "因為暴風雨,延誤是無法避免的。" },
    unbearable: { pos: "adj.", zh: "不能忍受的；令人不能容忍的", level: 2, diff: 45, ex: "The heat in the room was unbearable.", exZh: "房間裡的熱度令人無法忍受。" },
