    with_a_difference: { pos: "idiom", zh: "與眾不同，不同尋常，別具一格，更勝一籌", level: 2, diff: 65, ex: "This is a café with a difference: you can borrow books while you drink your coffee.", exZh: "這是一家別具一格的咖啡館：你可以一邊喝咖啡，一邊借書。" },
