    wittingly: { pos: "adv.", zh: "有意地；存心地", level: 3, diff: 70, ex: "She wittingly broke the rule.", exZh: "她是有意違反這項規定的。" },
    wizen: { pos: "v.", zh: "起皺；（使）乾癟", level: 3, diff: 90, ex: "The apple began to wizen in the sun.", exZh: "蘋果在陽光下開始乾癟。" },
    wizen_faced: { w: "wizen-faced", pos: "adj.", zh: "面孔乾瘦的", level: 3, diff: 90, ex: "The wizen-faced man watched us from the doorway.", exZh: "那個面孔乾瘦的男人在門口看著我們。" },
    working_man: { w: "working-man", pos: "n.", zh: "有工作的人", level: 2, diff: 50, ex: "The working-man leaves for his job early each morning.", exZh: "這名有工作的人每天一大早就出門上班。" },
    workmanlike: { pos: "adj.", zh: "技藝平平的；一般水準的", level: 3, diff: 70, ex: "He gave a workmanlike performance, completing the task efficiently without any flair.", exZh: "他做得熟練而稱職，效率很高，只是沒有特別出彩之處。" },
    workmanship: { pos: "n.", zh: "技藝；手藝；工藝", level: 2, diff: 65, ex: "The workmanship on this wooden chair is excellent.", exZh: "這把木椅的工藝非常出色。" },
    wrangle: { pos: "v.", zh: "爭吵；爭論", level: 3, diff: 75, ex: "The brothers wrangled over who should drive.", exZh: "兄弟倆為了誰要開車而爭吵。" },
    wreak: { pos: "v.", zh: "造成，引起（災禍等）", level: 3, diff: 70, ex: "A severe storm can wreak havoc on coastal towns.", exZh: "猛烈的風暴可能會對沿海城鎮造成嚴重破壞。" },
    wrest: { pos: "v.", zh: "辛苦謀求；費力取得", level: 3, diff: 75, ex: "The team had to wrest control of the building from the attackers.", exZh: "這支隊伍不得不從攻擊者手中奪取大樓的控制權。" },
    wretchedness: { pos: "n.", zh: "不幸，可憐；肮髒，惡劣", level: 3, diff: 75, ex: "The wretchedness of life in the camp was impossible to ignore.", exZh: "營地生活的悲慘境況令人無法忽視。" },
    writhe: { pos: "v.", zh: "扭動；蠕動", level: 3, diff: 75, ex: "The snake writhed on the ground.", exZh: "蛇在地上扭動。" },
