    writings_of: { pos: "n. phr.", zh: "著作，作品", level: 2, diff: 55, ex: "The writings of Jane Austen are still widely read.", exZh: "珍·奧斯汀的著作至今仍廣為閱讀。" },
    wry: { pos: "adj.", zh: "諷刺的；解嘲的", level: 3, diff: 75, ex: "She made a wry joke about her own mistake.", exZh: "她拿自己的錯誤開了一個帶點自嘲意味的玩笑。" },
    yearling: { pos: "adj./n.", zh: "一歲；滿一歲的動物；一歲馬", level: 2, diff: 65, ex: "The yearling horse ran across the field.", exZh: "那匹一歲大的馬跑過田野。" },
    zealot: { pos: "n.", zh: "狂熱者；熱心者", level: 3, diff: 75, ex: "The zealot spent every evening campaigning for the cause and refused to hear any criticism.", exZh: "那位狂熱者每晚都為這項事業奔走，拒絕聽取任何批評。" },
